import{_ as o,l,o as t,c as n,v as e,p as s,x as i,d as h,i as m,S as d}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"采样定理与成像","description":"","frontmatter":{"title":"采样定理与成像","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/sampling-theorem-imaging.md","filePath":"litho/sampling-theorem-imaging.md","lastUpdated":1789023840000}'),p={name:"litho/sampling-theorem-imaging.md"};function c(u,a,A,f,E,_){const r=l("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="采样定理与成像" tabindex="-1">采样定理与成像 <a class="header-anchor" href="#采样定理与成像" aria-label="Permalink to &quot;采样定理与成像&quot;">​</a></h1><div class="epigraph"><p>带限的像可以被离散点完全决定；网格粗过 Nyquist，折叠进来的不是「数值噪声」，而是假节距。</p><footer>—— Shannon 采样定理；光学带限与复原见 Goodman, Introduction to Fourier Optics</footer></div><p><a href="/litho/fourier-pairs-convolution">上一课</a>把成像收成卷积与傅里叶对。缺口是：计算光刻与计量都在<strong>网格</strong>上工作，还没有说格子必须有多密，才不把光瞳截止以外的假频率写进空中像。本课钉采样定理在成像里的用法。点扩散的连续核留给<a href="/litho/psf-airy">下一课</a>。不要把 Nyquist 频率写成产线 \\(k_1\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的 \\(T(\\mathbf{f})H(\\mathbf{f})\\) 是连续函数。机器里的掩模是多边形或像素，空中像是阵列，SEM 轮廓是采样点。Shannon：若信号频谱支撑在 \\(|f|\\lt f_c\\)，间隔 \\(\\Delta x\\le 1/(2f_c)\\) 的样点决定全部连续函数。光学像的 \\(f_c\\) 由光瞳给出，不是由设计节点名给出。</p><p>缺口因此是给空中像一条可写进网格的截止，而不是再列一次 rect–sinc。把「画得更密」当成精度，会在已经带限的像上浪费点；把网格取得比截止更疏，会让本不该进瞳的节距从折叠里冒出来——OPC 会去修一个光学上不存在的齿。</p><h3 id="两条截止不要混" tabindex="-1">两条截止不要混 <a class="header-anchor" href="#两条截止不要混" aria-label="Permalink to &quot;两条截止不要混&quot;">​</a></h3><p>相干场的带限是 \\(\\mathrm{NA}/\\lambda\\)（像方）；非相干强度的带限是 \\(2\\mathrm{NA}/\\lambda\\)，因为 \\(|U|^2\\) 的谱是场谱的自相关。<a href="/litho/mtf-optics">MTF 课</a>已经写过这两条。采样必须声明采的是场还是强度：采强度，间隔要按 \\(2\\mathrm{NA}/\\lambda\\) 的 Nyquist；采复振幅再平方，网格可以按场截止来，平方在离散上完成。部分相干介于两者之间，工程上按强度截止取样最安全。</p><p><span class="marginnote">掩模侧还有一次采样：电子束写像素、ILT 的像素掩模、曲线掩模的折线。那是物体 \\(t\\) 的离散，不是像的离散。物体可以有锐角（谱不带限），系统靠光瞳把像变成带限。不要用掩模像素去代替像面 Nyquist。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>像方空间频率以 \\(\\mathrm{NA}/\\lambda\\) 归一时，单位圆是相干截止。强度网格：</p> \\[\\Delta x \\lesssim \\frac{\\lambda}{4\\,\\mathrm{NA}} \\]<p>对应 \\(2\\mathrm{NA}/\\lambda\\) 的 Nyquist（再留一点抗混叠余量）。这是计算网格，不是「能印多细」——后者仍读<a href="/litho/rayleigh-litho">瑞利课</a>的工艺式，本课不重写。</p><p>抗混叠：连续光瞳硬切已经带限；数值上若先把物体 raster 成比光瞳更粗的 FFT，等于先混叠再滤波，假频进了通带。正确顺序是：物体频谱按光学截止铺足够零（或解析变换），乘 \\(P\\)，再逆变换到满足 Nyquist 的像面。</p>',14)),(t(),s(d,null,{default:i(()=>[m(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%89%A9%E9%A2%91%E8%B0%B1%20T%22%5D%20--%3E%20BAND%5B%22%E5%85%89%E7%9E%B3%E5%B8%A6%E9%99%90%22%5D%0A%20%20BAND%20--%3E%20NYQ%5B%22%E6%8C%89%E6%88%AA%E6%AD%A2%E9%80%89%20%CE%94x%22%5D%0A%20%20NYQ%20--%3E%20GRID%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E7%BD%91%E6%A0%BC%22%5D%0A%20%20COARSE%5B%22%E8%BF%87%E7%96%8F%E7%BD%91%E6%A0%BC%22%5D%20--%3E%20ALIAS%5B%22%E6%8A%98%E5%8F%A0%E5%81%87%E8%8A%82%E8%B7%9D%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="计量采样是另一条链" tabindex="-1">计量采样是另一条链 <a class="header-anchor" href="#计量采样是另一条链" aria-label="Permalink to &quot;计量采样是另一条链&quot;">​</a></h3><p>CD-SEM 的像素、散射测量的衍射级，受探测器与光学的另一套截止约束，不要把「仿真 Δx」抄进量测配方。本课只约束成像计算与掩模光栅化相对投影截止的关系。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>带限函数的信息量由截止面积决定。光瞳是有限圆，空中像的自由度大致是每个光学面积 \\((\\lambda/\\mathrm{NA})^2\\) 里若干个数——这就是为什么全芯片还可以用稀疏点加核来算，而不是每纳米一个独立像素。混叠的机制是周期延拓的谱叠进基带：看起来像某禁戒节距「突然有对比」，其实是邻区谱的折叠。</p><p>扫描狭缝沿扫描向做时间平均，等效于再乘一个 sinc 型的传递，并不放宽 Nyquist；它只再低通一次。不要把扫描平均当成可以加粗网格的许可证。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到离散空中像，默认网格满足强度 Nyquist，FFT 窗口盖住光学直径。SOCS 核、OPC 碎片求值都建立在这条带限上。下一课的 PSF 是连续核；落到网格时用本课的间隔去采样它。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>定理假定等晕、平移不变、理想带限。场点换 TCC、矢量通道、薄膜栈沿 \\(z\\) 的驻波，都不取消横向带限，只改变要采的是哪一张 \\(I(x,y)\\)。禁止把 Nyquist 与 \\(k_1\\) 互相换算成「节点分辨率」。也不引用未公开的 OPC 引擎缺省网格表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>空中像由光瞳带限；采样间隔由截止决定，不是由节点名决定。</li><li>强度截止 \\(2\\mathrm{NA}/\\lambda\\)，场截止 \\(\\mathrm{NA}/\\lambda\\)；声明采的是哪一个。</li><li>过疏网格制造假节距；过密网格不增加光学信息。</li><li>掩模像素与像面 Nyquist 是两次离散。</li><li>下一课：连续核 PSF / Airy。</li><li>出处：Shannon；Goodman, <em>Introduction to Fourier Optics</em>。</li></ul>',11))])}const q=o(p,[["render",c]]);export{N as __pageData,q as default};
